static const uint8_t cells[12] = {0, 5, 3, 7, 12, 10, 14, 25, 23, 21, 27, 29};
/* each selector's record, indoors and outdoors (src/graphics/scene.c monster_views) */
static const uint8_t indoor_record[26] = {156, 150, 153, 132, 130, 131, 106, 104, 105, 70, 68, 69, 128,
                                          129, 100, 102, 62, 65, 66, 67, 101, 103, 60, 63, 61, 64};
static const uint8_t outdoor_record[26] = {118, 112, 115, 94, 92, 93, 75, 73, 74, 52, 50, 51, 90,
                                           91, 69, 71, 44, 47, 48, 49, 70, 72, 42, 45, 43, 46};
static xeen_movement m, input;
static uint8_t database[60 * 8];

static void image(unsigned world, unsigned outdoor)
{
    memset(&m, 0, sizeof m);
    memcpy(m.ds, xeen_program_ds_image, XEEN_PROGRAM_DS_SIZE);
    m.ds[XEEN_DS_WORLD] = (uint8_t)world;
    xeen_write16(&m, XEEN_DS_OUTDOORS, outdoor ? 0x8000u : 0u);
}
static void stand(unsigned i, unsigned cell)
{
    uint16_t at = (uint16_t)XEEN_MAP_MONSTER(i);
    unsigned f = m.ds[XEEN_DS_PARTY_DIRECTION];
    memset(m.ds + at, 0, XEEN_MAP_MONSTER_BYTES);
    m.ds[at] = (uint8_t)(m.ds[XEEN_DS_PARTY_X] + m.ds[XEEN_DS_STEP_X(f, cell + 2u)]);
    m.ds[at + 1u] = (uint8_t)(m.ds[XEEN_DS_PARTY_Y] + m.ds[XEEN_DS_STEP_Y(f, cell + 2u)]);
}
static int placement(const placement_case *c, unsigned n)
{
    unsigned i, k, count = 0;
    uint16_t list = c->outdoor ? XEEN_DS_OUTDOOR_VIEW_LIST : XEEN_DS_INDOOR_VIEW_LIST;
    xeen_status s;
    image(c->world, c->outdoor);
    m.ds[XEEN_DS_PARTY_DIRECTION] = c->facing;
    m.ds[XEEN_DS_PARTY_X] = 8;
    m.ds[XEEN_DS_PARTY_Y] = 8;
    memset(m.ds + XEEN_DS_VIEW_WALLS, 0, XEEN_VIEW_WALLS_BYTES);
    for (k = 0; k < 26; k++) {
        uint16_t r = (uint16_t)(XEEN_DS_OUTDOOR_VIEW_LIST +
                                XEEN_VIEW_RECORD_BYTES * xeen_read16(&m, (uint16_t)(XEEN_DS_OUTDOOR_MONSTER_RECORDS + 2u * k)));
        xeen_write16(&m, (uint16_t)(r + XEEN_VIEW_RECORD_FRAME), XEEN_VIEW_RECORD_UNUSED);
    }
    for (i = 0; i < c->monsters; i++) {
        stand(count++, c->cell);
    }
    for (i = 0; c->others && i < 12; i++) {
        if (cells[i] != c->cell) {
            stand(count++, cells[i]);
        }
    }
    m.ds[XEEN_DS_MAP_MONSTER_COUNT] = (uint8_t)count;
    m.ds[XEEN_DS_MAP_OBJECT_COUNT] = 0;
    s = c->outdoor ? xeen_scene_outdoor_monsters(&m, database, sizeof database)
                   : xeen_scene_monsters(&m, database, sizeof database);
    if (s != XEEN_OK) {
        printf("placement %u: status %d\n", n, (int)s);
        return 1;
    }
    for (k = 0; k < 26; k++) {
        unsigned r = c->outdoor ? outdoor_record[k] : indoor_record[k];
        int16_t x = (int16_t)xeen_read16(&m, (uint16_t)(list + XEEN_VIEW_RECORD_BYTES * r + XEEN_VIEW_RECORD_X));
        if (m.ds[XEEN_DS_VIEW_MONSTER(k)] != c->selectors[k] || x != c->x[k]) {
            printf("placement %u (%s, world %u, cell %u, %u monsters, others %u): slot %u selector %u/%u x %d/%d\n", n,
                   c->outdoor ? "outdoors" : "indoors", c->world, c->cell, c->monsters, c->others, k,
                   m.ds[XEEN_DS_VIEW_MONSTER(k)], c->selectors[k], x, c->x[k]);
            return 1;
        }
    }
    return 0;
}
static int hits(const hit_case *c, unsigned n)
{
    uint16_t table = c->outdoor ? XEEN_DS_OUTDOOR_HIT_EFFECT_RECORDS : XEEN_DS_HIT_EFFECT_RECORDS;
    unsigned s, i, changed = 0;
    unsigned long long h = 1469598103934665603ull;
    image(c->world, c->outdoor);
    for (s = 0; s < 3; s++) {
        xeen_write16(&m, (uint16_t)(table + 2u * s), c->words[s]);
        m.ds[XEEN_DS_HIT_FRAMES + s] = (uint8_t)c->values[5u * s];
        m.ds[XEEN_DS_HIT_PHYSICAL + s] = (uint8_t)c->values[5u * s + 1u];
        m.ds[XEEN_DS_HIT_ELEMENT + s] = (uint8_t)c->values[5u * s + 2u];
        xeen_write16(&m, (uint16_t)(XEEN_DS_HIT_DAMAGE_SCALE + 2u * s), c->values[5u * s + 3u]);
        xeen_write16(&m, (uint16_t)(XEEN_DS_HIT_ELEMENT_SCALE + 2u * s), c->values[5u * s + 4u]);
    }
    m.ds[XEEN_DS_VIEW_MONSTER(1)] = c->slot_1;
    m.ds[XEEN_DS_VIEW_MONSTER(2)] = c->slot_2;
    input = m;
    if (c->outdoor) {
        (void)xeen_scene_outdoor_effects(&m);
    } else {
        (void)xeen_scene_prepare_effects(&m);
    }
    for (i = 0; i < 65536u; i++) {
        changed += m.ds[i] != input.ds[i];
        h = (h ^ m.ds[i]) * 1099511628211ull;
    }
    if (changed != c->changed || h != c->digest) {
        printf("hits %u (%s): %u changed bytes / %u, digest %016llx / %016llx\n", n, c->outdoor ? "outdoors" : "indoors",
               changed, c->changed, h, c->digest);
        return 1;
    }
    return 0;
}
int main(void)
{
    unsigned n, failed = 0, pairs = 0, aliased = 0;
    for (n = 0; n < sizeof placement_cases / sizeof placement_cases[0]; n++) {
        failed += (unsigned)placement(&placement_cases[n], n);
        pairs += placement_cases[n].monsters == 2u;
    }
    for (n = 0; n < sizeof hit_cases / sizeof hit_cases[0]; n++) {
        failed += (unsigned)hits(&hit_cases[n], n);
        aliased += hit_cases[n].words[0] > 200u || hit_cases[n].words[1] > 200u || hit_cases[n].words[2] > 200u;
    }
    /* the table must not be vacuous: pair cells in both lists, aliased record words */
    if (pairs < 40u || aliased < 60u) {
        printf("vacuous table: %u pair cases, %u aliased hit cases\n", pairs, aliased);
        return 1;
    }
    printf("%u placement cases, %u hit cases, %u failed\n", (unsigned)(sizeof placement_cases / sizeof placement_cases[0]),
           (unsigned)(sizeof hit_cases / sizeof hit_cases[0]), failed);
    return failed ? 1 : 0;
}
